/**
 * This agent's standing on one wallet, on one chain, for one token.
 *
 * Two booleans rather than one `attached`, because the two states they name
 * are both real: a module can be enabled on the Safe while it has no code
 * (an attachment that skipped the deploy), and a module can have code while
 * the Safe has not enabled it (the deploy landed, the enable did not).
 */
public struct AgentMandate {
    /**
     * The Safe asked about.
     */
    public var wallet: String
    public var chainId: UInt64
    /**
     * This agent's P256ExecutorModule on that Safe, derived from
     * `(wallet, own signer key)`.
     */
    public var executorModule: String
    /**
     * `eth_getCode(executor_module)` is non-empty.
     */
    public var moduleDeployed: Bool
    /**
     * `Safe.isModuleEnabled(executor_module)`.
     */
    public var moduleEnabled: Bool
    /**
     * The token the limit below is denominated in.
     */
    public var token: String
    /**
     * Per-transaction ceiling, in the token's smallest unit. Zero means the
     * module may spend nothing: the owner set it to zero, or the guard holds
     * no limit for this module and token at all.
     */
    public var maxPerTx: U256
    /**
     * Daily cap, same unit. Zero means zero, as for `max_per_tx`.
     */
    public var dailyMax: U256
    /**
     * Spent so far today, same unit.
     */
    public var spent: U256

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The Safe asked about.
         */wallet: String, chainId: UInt64, 
        /**
         * This agent's P256ExecutorModule on that Safe, derived from
         * `(wallet, own signer key)`.
         */executorModule: String, 
        /**
         * `eth_getCode(executor_module)` is non-empty.
         */moduleDeployed: Bool, 
        /**
         * `Safe.isModuleEnabled(executor_module)`.
         */moduleEnabled: Bool, 
        /**
         * The token the limit below is denominated in.
         */token: String, 
        /**
         * Per-transaction ceiling, in the token's smallest unit. Zero means the
         * module may spend nothing: the owner set it to zero, or the guard holds
         * no limit for this module and token at all.
         */maxPerTx: U256, 
        /**
         * Daily cap, same unit. Zero means zero, as for `max_per_tx`.
         */dailyMax: U256, 
        /**
         * Spent so far today, same unit.
         */spent: U256) {
        self.wallet = wallet
        self.chainId = chainId
        self.executorModule = executorModule
        self.moduleDeployed = moduleDeployed
        self.moduleEnabled = moduleEnabled
        self.token = token
        self.maxPerTx = maxPerTx
        self.dailyMax = dailyMax
        self.spent = spent
    }
}

