extension AgentMandate: Equatable, Hashable {
    public static func ==(lhs: AgentMandate, rhs: AgentMandate) -> Bool {
        if lhs.wallet != rhs.wallet {
            return false
        }
        if lhs.chainId != rhs.chainId {
            return false
        }
        if lhs.executorModule != rhs.executorModule {
            return false
        }
        if lhs.moduleDeployed != rhs.moduleDeployed {
            return false
        }
        if lhs.moduleEnabled != rhs.moduleEnabled {
            return false
        }
        if lhs.token != rhs.token {
            return false
        }
        if lhs.maxPerTx != rhs.maxPerTx {
            return false
        }
        if lhs.dailyMax != rhs.dailyMax {
            return false
        }
        if lhs.spent != rhs.spent {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(wallet)
        hasher.combine(chainId)
        hasher.combine(executorModule)
        hasher.combine(moduleDeployed)
        hasher.combine(moduleEnabled)
        hasher.combine(token)
        hasher.combine(maxPerTx)
        hasher.combine(dailyMax)
        hasher.combine(spent)
    }
