/**
 * The record that a payment settled, whoever holds it.
 *
 * The two rails differ in who can prove it, and this is the one shape that
 * carries either: where the server settles, `receipt_header` names the header
 * it reported under and `value` is what it sent; where the payer settles
 * first, `receipt_header` is absent and `value` is the credential the payer
 * obtained by paying. Kept verbatim and never decoded -- presence is the
 * proof, and a value that will not decode does not un-spend the money.
 */
public struct PaySettlement {
    /**
     * The response header the server reported the settlement under. `None`
     * where the payer held the proof instead.
     */
    public var receiptHeader: String?
    /**
     * The receipt, or the payer's own proof, exactly as it was produced.
     */
    public var value: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The response header the server reported the settlement under. `None`
         * where the payer held the proof instead.
         */receiptHeader: String?, 
        /**
         * The receipt, or the payer's own proof, exactly as it was produced.
         */value: String) {
        self.receiptHeader = receiptHeader
        self.value = value
    }
}

