extension X402EscalationRequest: Equatable, Hashable {
    public static func ==(lhs: X402EscalationRequest, rhs: X402EscalationRequest) -> Bool {
        if lhs.chainId != rhs.chainId {
            return false
        }
        if lhs.network != rhs.network {
            return false
        }
        if lhs.safeAddress != rhs.safeAddress {
            return false
        }
        if lhs.payTo != rhs.payTo {
            return false
        }
        if lhs.amount != rhs.amount {
            return false
        }
        if lhs.asset != rhs.asset {
            return false
        }
        if lhs.maxTimeoutSeconds != rhs.maxTimeoutSeconds {
            return false
        }
        if lhs.eip712Name != rhs.eip712Name {
            return false
        }
        if lhs.eip712Version != rhs.eip712Version {
            return false
        }
        if lhs.resourceUrl != rhs.resourceUrl {
            return false
        }
        if lhs.resourceDescription != rhs.resourceDescription {
            return false
        }
        if lhs.webOrigin != rhs.webOrigin {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(chainId)
        hasher.combine(network)
        hasher.combine(safeAddress)
        hasher.combine(payTo)
        hasher.combine(amount)
        hasher.combine(asset)
        hasher.combine(maxTimeoutSeconds)
        hasher.combine(eip712Name)
        hasher.combine(eip712Version)
        hasher.combine(resourceUrl)
        hasher.combine(resourceDescription)
        hasher.combine(webOrigin)
    }
}



