     */
    case notEnrolled
    /**
     * The agent may draw up to `up_to` itself.
     */
    case available(upTo: UInt64
    )
    /**
     * The limit is too spent to restore the keep target.
     */
    case blocked(wanted: UInt64, available: UInt64, unblocksAtMs: Int64?
    )
}


