// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What came of asking for a resource that may cost money.
 *
 * A tagged union rather than a flat record with optional fields, because the
 * combinations a flat record allows are the ones that must not exist: a
 * refusal carrying a settlement, or a paid result naming no rail. A host
 * switches on the variant and every field it then reads is one that belongs
 * to that answer.
 *
 * The three money-bearing variants are the loud ones.
 * [`PaidNotServed`](PayResult::PaidNotServed) in particular is not an error:
 * the money is gone and the resource is not, on rails with no refund path, so
 * it is a result a caller has to see rather than an exception it may swallow.
 */

public enum PayResult {
    
    /**
     * The server served the resource and asked for nothing.
     */
    case served(response: PayResponse
    )
    /**
     * Payment was made, it settled, and the resource came with it.
     */
    case paidAndServed(rail: String, 
        /**
         * The payer's own label for how it signed.
         */scheme: String?, settlement: PaySettlement?, response: PayResponse
    )
    /**
     * Payment was made and settled, and the server did not serve the
     * resource. The money is gone and there is no refund path.
     */
    case paidNotServed(rail: String, scheme: String?, settlement: PaySettlement?, response: PayResponse
    )
    /**
     * The server refused and settled nothing. The only variant that promises
     * a payment was attempted and no money moved.
     */
    case rejected(rail: String, scheme: String?, response: PayResponse
    )
    /**
     * Nothing was paid: the silent tier may not pay this, and the owner can
     * authorize the payment itself.
     */
    case ownerApprovalNeeded(rail: String
    )
    /**
     * Nothing was paid: the agent's own Lightning pocket cannot settle the
     * invoice. The owner tops that pocket up and the call is retried; the
     * owner is never asked to pay the merchant.
     */
    case pocketTopUpNeeded(rail: String, sideWalletIndex: UInt32, 
        /**
         * What the invoice asks for, in sats -- an upper bound on the
         * shortfall, since a node's spendable liquidity is not read here.
         */amountSats: UInt64
    )
}


#if compiler(>=6)
extension PayResult: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePayResult: FfiConverterRustBuffer {
    typealias SwiftType = PayResult

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PayResult {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .served(response: try FfiConverterTypePayResponse.read(from: &buf)
        )
        
        case 2: return .paidAndServed(rail: try FfiConverterString.read(from: &buf), scheme: try FfiConverterOptionString.read(from: &buf), settlement: try FfiConverterOptionTypePaySettlement.read(from: &buf), response: try FfiConverterTypePayResponse.read(from: &buf)
        )
        
        case 3: return .paidNotServed(rail: try FfiConverterString.read(from: &buf), scheme: try FfiConverterOptionString.read(from: &buf), settlement: try FfiConverterOptionTypePaySettlement.read(from: &buf), response: try FfiConverterTypePayResponse.read(from: &buf)
        )
        
        case 4: return .rejected(rail: try FfiConverterString.read(from: &buf), scheme: try FfiConverterOptionString.read(from: &buf), response: try FfiConverterTypePayResponse.read(from: &buf)
        )
        
        case 5: return .ownerApprovalNeeded(rail: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .pocketTopUpNeeded(rail: try FfiConverterString.read(from: &buf), sideWalletIndex: try FfiConverterUInt32.read(from: &buf), amountSats: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PayResult, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .served(response):
            writeInt(&buf, Int32(1))
            FfiConverterTypePayResponse.write(response, into: &buf)
            
        
        case let .paidAndServed(rail,scheme,settlement,response):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(rail, into: &buf)
            FfiConverterOptionString.write(scheme, into: &buf)
            FfiConverterOptionTypePaySettlement.write(settlement, into: &buf)
            FfiConverterTypePayResponse.write(response, into: &buf)
            
        
        case let .paidNotServed(rail,scheme,settlement,response):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(rail, into: &buf)
            FfiConverterOptionString.write(scheme, into: &buf)
            FfiConverterOptionTypePaySettlement.write(settlement, into: &buf)
            FfiConverterTypePayResponse.write(response, into: &buf)
            
        
        case let .rejected(rail,scheme,response):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(rail, into: &buf)
            FfiConverterOptionString.write(scheme, into: &buf)
            FfiConverterTypePayResponse.write(response, into: &buf)
            
        
        case let .ownerApprovalNeeded(rail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(rail, into: &buf)
            
        
        case let .pocketTopUpNeeded(rail,sideWalletIndex,amountSats):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(rail, into: &buf)
            FfiConverterUInt32.write(sideWalletIndex, into: &buf)
            FfiConverterUInt64.write(amountSats, into: &buf)
            
        }
    }
}


